import uiautomation as auto
auto.SetGlobalSearchTimeout(1)
root=auto.ControlFromHandle(462320)
count=0
def walk(c,depth=0):
    global count
    if count>=500 or depth>7:
        return
    try:
        name=c.Name
    except Exception:
        name=""
    try:
        aid=c.AutomationId
    except Exception:
        aid=""
    try:
        ct=c.ControlTypeName
    except Exception:
        ct=""
    try:
        cls=c.ClassName
    except Exception:
        cls=""
    if name or aid or ct:
        print(f"{depth}|{ct}|{aid}|{cls}|{name}")
        count+=1
    try:
        kids=c.GetChildren()
    except Exception:
        return
    for k in kids:
        walk(k,depth+1)
walk(root)
print("COUNT",count)
